        _low_signal_purposes = {
            "character_event_reverse_track",
            "counter_evidence_title_track",
            "counter_evidence_genre_track",
            "counter_evidence_character_track",
            "abbreviation_meaning_search",
            "abbreviation_fullname_search",
            "ambiguous_meaning_track",
        }

        _anchor_terms_for_prune: set[str] = set()
        if _smart_prune_on and ctx_ref is not None:
            try:
                _gk_for_prune = ctx_ref.get_expert_output(ExpertType.GATEKEEPER) or {}
                _gk_entities = _gk_for_prune.get("detected_entities") or {}
                _generic_anchor_block = {
                    "스포", "소설", "웹소설", "작가", "리뷰", "후기", "결말", "작품", "장르"
                }
                for _cand in (_gk_entities.get("possible_titles") or []):
                    _norm = self._normalize_kor_token(_cand)
                    if len(_norm) >= 3 and _norm not in _generic_anchor_block:
                        _anchor_terms_for_prune.add(_norm)
                for _cand in (_gk_for_prune.get("key_terms") or []):
                    _norm = self._normalize_kor_token(_cand)
                    if len(_norm) >= 3 and _norm not in _generic_anchor_block:
                        _anchor_terms_for_prune.add(_norm)
            except Exception:
                _anchor_terms_for_prune = set()

        seen_queries: set[str] = set()
        processed_query_keys: set[str] = set()
        query_family_counts: Dict[str, int] = {}
        _zero_streak = 0
        _zero_total = 0
        _nonzero_total = 0
        _title_body_context_markers = ("ts", "환생", "회귀", "빙의", "인방", "배우", "노맨스", "재벌", "커뮤니티")

        def _title_body_probe_context_hit_count(query: str) -> int:
            q_raw_lc = str(query or "").lower()
            q_norm = self._normalize_kor_token(query)
            hits = 0
            for marker in _title_body_context_markers:
                if marker.isascii():
                    if marker in q_raw_lc:
                        hits += 1
                elif self._normalize_kor_token(marker) in q_norm:
                        hits += 1
            return hits

        _title_body_specific_query_stop_terms = {
            self._normalize_kor_token(term)
            for term in (
                "ts",
                "환생",
                "회귀",
                "빙의",
                "헌터",
                "인방",
                "노맨스",
                "배우",
                "웹소설",
                "소설",
                "장르소설",
                "노벨피아",
                "노피아",
                "문피아",
                "카카페",
                "시리즈",
                "novelpia",
                "site",
                "novel",
            )
        }
        _title_body_specific_query_blocked_terms = {
            self._normalize_kor_token(term)
            for term in ("뷰지", "자지", "보지", "질싸", "섹스", "야스", "쿠키", "초콜릿", "디저트")
        }

        def _title_body_probe_core_hit_count(query: str) -> int:
            hits: set[str] = set()
            for token in self._extract_query_tokens(query, keep_generic=False):
                norm = self._normalize_kor_token(token)
                if len(norm) < 2:
                    continue
                if norm in _title_body_specific_query_stop_terms:
                    continue
                if norm in _title_body_specific_query_blocked_terms:
                    continue
                hits.add(norm)
            return len(hits)

        def _is_specific_title_body_probe_query(query: str) -> bool:
            raw = str(query or "")
            raw_lc = raw.lower()
            raw_norm = self._normalize_kor_token(raw)
            platform_hint = bool(
                "site:novelpia.com" in raw_lc
                or "novelpia" in raw_lc
                or "노벨피아" in raw
                or "노피아" in raw
            )
            core_hits = _title_body_probe_core_hit_count(raw)
            quoted_core = raw.count('"') >= 4 and core_hits >= 2
            anchor_hit = bool(
                _anchor_terms_for_rerank
                and any(anchor and anchor in raw_norm for anchor in _anchor_terms_for_rerank)
            )
            return bool(
                _title_body_probe_context_hit_count(raw) >= 2
                or (platform_hint and core_hits >= 2)
                or (platform_hint and anchor_hit)
                or quoted_core
            )

        def _has_unseen_specific_title_body_probe() -> bool:
            for _, _, _, _remaining in sortable:
                _rq = str((_remaining or {}).get("query", "")).strip()
                if not _rq:
                    continue
                _rq_key = " ".join(_rq.replace('"', "").replace("'", "").split()).lower()
                if _rq_key in seen_queries:
                    continue
                if _purpose_key((_remaining or {}).get("purpose", "")) != "title_body_sanitized_platform_probe":
                    continue
                if _is_specific_title_body_probe_query(_rq):
                    return True
            return False

        def _is_direct_worklike_alias_probe_query(query: str, purpose_key: str) -> bool:
            q_norm = self._normalize_kor_token(query)
            return bool(
                _direct_worklike_alias_probe_norms
                and q_norm
                and purpose_key
                in {
                    "official_title_verify",
                    "platform_title_search",
                    "title_search_community",
                    "community_site_probe",
                    "alias_raw_probe",
                    "alias_bridge_search",
                    "title_anchor_exact_probe",
                    "title_anchor_official_probe",
                    "author_verify",
                    "author_disambiguation",
                    "adaptive_abbreviation",
                    "abbreviation_fullname_search",
                    "abbreviation_meaning_search",
                }
                and any(alias_norm and alias_norm in q_norm for alias_norm in _direct_worklike_alias_probe_norms)
            )

        def _has_unprocessed_direct_worklike_alias_probe() -> bool:
            for _, _, _, _remaining in sortable:
                _rq = str((_remaining or {}).get("query", "")).strip()
                if not _rq:
                    continue
                _rq_key = " ".join(_rq.replace('"', "").replace("'", "").split()).lower()
                if _rq_key in processed_query_keys:
                    continue
                if _is_direct_worklike_alias_probe_query(
                    _rq,
                    _purpose_key((_remaining or {}).get("purpose", "")),
                ):
                    return True
            return False

        _low_info_guard_purposes = {
            "official_title_verify",
            "platform_title_search",
            "title_search_community",
            "title_anchor_exact_probe",
            "title_anchor_official_probe",
            "author_verify",
            "character_verify",
            "community_chain_search",
            "discourse_suggestion",
            "alias_raw_probe",
            "abbreviation_split_search",
            "abbreviation_deep_split_search",
        }
        _weak_single_query_tokens = {
            "이제", "이제는", "지금", "오늘", "이번", "그냥", "진짜", "가자",
            "됐다", "되었다", "예감", "무슨", "어디", "나오는", "뭐", "저거",
            "이거", "올때", "올", "맞다", "마따",
        }

        def _is_weak_prefix_fragment(_norm_token: str) -> bool:
            if not _norm_token:
                return False
            return any(
                _norm_token != _weak
                and len(_norm_token) <= len(_weak) + 2
                and _norm_token.startswith(_weak)
                for _weak in _weak_single_query_tokens
                if _weak
            )

        def _get_low_info_query_reason(_query: str, _purpose_key: str) -> Optional[str]:
            if _purpose_key not in _low_info_guard_purposes:
                return None
            _core_tokens = self._extract_query_tokens(_query, keep_generic=False)
            if not _core_tokens:
                return "검색 핵심 토큰이 없음"
            _strong_tokens: List[str] = []
            for _tok in _core_tokens:
                _norm = self._normalize_kor_token(_tok)
                if not _norm:
                    continue
                if _norm in _weak_single_query_tokens or _is_weak_prefix_fragment(_norm):
                    continue
                _strong_tokens.append(_norm)
            if _strong_tokens:
                return None
            if len(_core_tokens) == 1:
                _only_norm = self._normalize_kor_token(_core_tokens[0])
                if _is_weak_prefix_fragment(_only_norm):
                    return f"단일 일반어 접두 파편 토큰('{_core_tokens[0]}')만 남음"
                return f"단일 일반어/기능어 토큰('{_core_tokens[0]}')만 남음"
            return "핵심 토큰이 일반어/기능어뿐"

        _early_stop_critical_purposes = {
            "official_title_verify",
            "platform_title_search",
            "title_search_community",
            "title_anchor_exact_probe",
            "title_anchor_official_probe",
            "character_verify",
            "author_verify",
            "abbreviation_verification",
            "alias_bridge_search",
            "key_term_novel_search",
            "search_floor_backfill",
            "community_site_probe",
            "unresolved_term_novel",
        }
        _zero_stop_toggle = os.getenv("LLM_ENABLE_ZERO_RESULT_EARLY_STOP", "1").strip().lower()
        _zero_stop_enabled = _zero_stop_toggle in {"1", "true", "yes", "on"}
        try:
            _zero_stop_streak_limit = int(os.getenv("LLM_ZERO_RESULT_STREAK_LIMIT", "6"))
        except Exception:
            _zero_stop_streak_limit = 6
        try:
            _zero_stop_min_queries = int(os.getenv("LLM_ZERO_RESULT_MIN_QUERIES", "10"))
        except Exception:
            _zero_stop_min_queries = 10
        _zero_stop_streak_limit = max(2, min(_zero_stop_streak_limit, 30))
        _zero_stop_min_queries = max(1, min(_zero_stop_min_queries, 100))
        try:
            _search_concurrency = int(os.getenv("PIPELINE_SEARCH_CONCURRENCY", "2"))
        except Exception:
            _search_concurrency = 2
        if self.parallel_count > 1:
            _search_concurrency = min(_search_concurrency, 2)
        _search_concurrency = max(1, min(_search_concurrency, 4))
        _search_owner = getattr(self.search_fn, "__self__", None)
        _search_with_meta = getattr(_search_owner, "_search_with_meta", None) if _search_owner is not None else None
        _can_parallel_search = _search_concurrency > 1 and callable(_search_with_meta)

        def _invoke_search_call(_query: str, _purpose: Any, _q_key: str) -> tuple[list[dict], dict]:
            if callable(_search_with_meta):
                _results, _meta = _search_with_meta(_query, str(_purpose or ""))
                return (
                    _results if isinstance(_results, list) else [],
                    _meta if isinstance(_meta, dict) else {},
                )

            _results = self.search_fn(_query, str(_purpose or ""))
            _result_list = _results if isinstance(_results, list) else []
            _search_meta: Dict[str, Any] = {}
            try:
                _owner = getattr(self.search_fn, "__self__", None)
                _last_meta = getattr(_owner, "_last_search_meta", None) if _owner is not None else None
                if isinstance(_last_meta, dict):
                    _meta_q = " ".join(str(_last_meta.get("query_norm", "")).split()).lower()
                    if _meta_q and _meta_q == _q_key:
                        _search_meta = _last_meta
            except Exception:
                _search_meta = {}
            return _result_list, _search_meta

        def _process_search_outcome(
            _query: str,
            _purpose: Any,
            _result_list: List[Dict[str, Any]],
            _search_meta: Dict[str, Any],
        ) -> bool:
            nonlocal _zero_streak, _zero_total, _nonzero_total
            _processed_q_key = " ".join(str(_query or "").replace('"', "").replace("'", "").split()).lower()
            if _processed_q_key:
                processed_query_keys.add(_processed_q_key)

            _meta_degraded = bool(_search_meta.get("degraded")) or bool(_search_meta.get("possible_throttle"))
            _meta_attempts = int(_search_meta.get("attempts") or 1)
            _meta_retries = int(_search_meta.get("retry_count") or 0)
            _meta_raw_total = int(_search_meta.get("raw_total") or len(_result_list))
            _meta_raw_preview = _search_meta.get("raw_preview") or []
            if not isinstance(_meta_raw_preview, list):
                _meta_raw_preview = []
            _meta_filtered_preview = _search_meta.get("filtered_preview") or []
            if not isinstance(_meta_filtered_preview, list):
                _meta_filtered_preview = []
            _meta_lang_filtered = int(_search_meta.get("lang_filtered") or 0)
            _meta_lang_filter_reasons = _search_meta.get("lang_filter_reasons") or {}
            if not isinstance(_meta_lang_filter_reasons, dict):
                _meta_lang_filter_reasons = {}
            _meta_requested_language = str(_search_meta.get("requested_language") or "").strip()
            _meta_provider_url = str(_search_meta.get("provider_url") or "").strip()
            _meta_headless_used = bool(_search_meta.get("headless_used"))
            _meta_headless_reason = str(_search_meta.get("headless_reason") or "").strip()
            try:
                _meta_headless_count = int(_search_meta.get("headless_count") or 0)
            except Exception:
                _meta_headless_count = 0
            _meta_headless_blocked = bool(_search_meta.get("headless_blocked"))
            _meta_fallback_recovered = bool(_search_meta.get("fallback_recovered"))
            _meta_degraded_recovered = bool(_search_meta.get("degraded_recovered"))
            _meta_direct_used = bool(_search_meta.get("direct_search_used"))
            _meta_direct_reason = str(_search_meta.get("direct_search_reason") or "").strip()
            try:
                _meta_direct_count = int(_search_meta.get("direct_search_count") or 0)
            except Exception:
                _meta_direct_count = 0
            _meta_direct_providers = [
                str(provider).strip()
                for provider in (_search_meta.get("direct_search_providers") or [])
                if str(provider).strip()
            ]
            _meta_direct_errors = [
                str(err).strip()
                for err in (_search_meta.get("direct_search_errors") or [])
                if str(err).strip()
            ]

            _bridge_reason_info = ""
            if _meta_lang_filter_reasons:
                _pairs: List[str] = []
                for _reason_key, _reason_count in sorted(
                    _meta_lang_filter_reasons.items(),
                    key=lambda kv: (-int(kv[1] or 0), str(kv[0])),
                )[:3]:
                    try:
                        _count_int = int(_reason_count)
                    except Exception:
                        continue
                    if _count_int <= 0:
                        continue
                    _pairs.append(f"{_reason_key} {_count_int}")
                if _pairs:
                    _bridge_reason_info = f" ({', '.join(_pairs)})"
            _bridge_request_info = ""
            if _meta_requested_language or _meta_provider_url:
                _bridge_context = []
                if _meta_requested_language:
                    _bridge_context.append(f"lang={_meta_requested_language}")
                if _meta_provider_url:
                    _bridge_context.append(f"provider={_meta_provider_url}")
                if _bridge_context:
                    _bridge_request_info = f", {' '.join(_bridge_context)}"
            _headless_info = ""
            if _meta_headless_used or _meta_headless_reason or _meta_headless_blocked:
                _headless_parts = []
                if _meta_headless_reason:
                    _headless_parts.append(f"reason={_meta_headless_reason}")
                _headless_parts.append(f"count={_meta_headless_count}")
                if _meta_headless_blocked:
                    _headless_parts.append("blocked=True")
                _headless_info = f", headless({' '.join(_headless_parts)})"
            _direct_info = ""
            if _meta_direct_used or _meta_direct_reason or _meta_direct_errors:
                _direct_parts = []
                if _meta_direct_reason:
                    _direct_parts.append(f"reason={_meta_direct_reason}")
                _direct_parts.append(f"count={_meta_direct_count}")
                if _meta_direct_providers:
                    _direct_parts.append(f"providers={','.join(_meta_direct_providers[:3])}")
                if _meta_direct_errors:
                    _direct_parts.append(f"errors={len(_meta_direct_errors)}")
                _direct_info = f", direct({' '.join(_direct_parts)})"
            _recovered_info = ", fallback_recovered" if _meta_fallback_recovered else ""

            _HARD_BLOCK_DOMAINS = [
                "huggingface.co", "github.com", "scribd.com",
                "wikipedia.org", "wikisource.org", "wiktionary.org",
                "youtube.com", "twitter.com", "facebook.com",
                "instagram.com", "tiktok.com", "hinative.com",
                "zhihu.com", "support.microsoft.com", "learn.microsoft.com",
            ]
            new_results = []
            deferred_results = []
            filtered_count = 0
            short_alias_false_official_count = 0
            soft_filtered_count = 0
            self_ref_count = 0
            duplicate_samples: List[str] = []
            current_post_id_str = str(post_id) if post_id else ""
            _purpose_key_current = _purpose_key(str(_purpose or ""))
            _query_norm_current = self._normalize_kor_token(_query)
            for _r in _result_list:
                url = _r.get("url", "")
                url_lower = (url or "").lower()
                title = str(_r.get("title") or "제목없음").strip()

                if current_post_id_str and url and current_post_id_str in url and "dcinside.com" in url:
                    self_ref_count += 1
                    continue

                if any(d in url_lower for d in _HARD_BLOCK_DOMAINS):
                    filtered_count += 1
                    continue

                is_relevant = self._is_relevant_result(_r, _query)
                if (
                    str(_budget_profile.get("profile") or "") == "short_alias_bridge"
                    and _short_alias_bridge_norms
                    and any(alias and alias in _query_norm_current for alias in _short_alias_bridge_norms)
                    and url
                    and self._is_novel_platform_url(url)
                    and self._is_novel_detail_url(url)
                ):
                    # Short community aliases often share one token with many unrelated
                    # official titles. Treat alias-query official details as bridge
                    # evidence only when the result itself preserves the alias.
                    result_norm = self._normalize_kor_token(
                        " ".join(str(_r.get(k) or "") for k in ("title", "content", "snippet"))
                    )
                    if result_norm and not any(alias and alias in result_norm for alias in _short_alias_bridge_norms):
                        bridge_phrase = _short_alias_official_supported_by_community_bridge(result_norm)
                        if bridge_phrase:
                            _r["_short_alias_bridge_phrase"] = bridge_phrase
                        else:
                            short_alias_false_official_count += 1
                            continue

                if url and url not in seen_urls:
                    _url_n = ConversationContext._normalize_url_for_dedup(url)
                    if _url_n in seen_urls_norm:
                        if len(duplicate_samples) < 3:
                            duplicate_samples.append(title[:50])
                        continue
                    seen_urls.add(url)
                    seen_urls_norm.add(_url_n)
                    r_copy = _r.copy()
                    r_copy["_query"] = _query
                    r_copy["_purpose"] = _purpose
                    if is_relevant:
                        new_results.append(r_copy)
                    else:
                        r_copy["_soft_irrelevant"] = True
                        soft_filtered_count += 1
                        deferred_results.append(r_copy)
                elif not url:
                    r_copy = _r.copy()
                    r_copy["_query"] = _query
                    r_copy["_purpose"] = _purpose
                    if is_relevant:
                        new_results.append(r_copy)
                    else:
                        r_copy["_soft_irrelevant"] = True
                        soft_filtered_count += 1
                        deferred_results.append(r_copy)
                else:
                    if len(duplicate_samples) < 3:
                        duplicate_samples.append(title[:50])

            def _filtered_official_detail_matches_known_alias(_item: Dict[str, Any]) -> bool:
                if _purpose_key_current not in {
                    "title_anchor_official_probe",
                    "known_title_abbreviation_official_url_recall",
                    "official_title_verify",
                    "platform_title_search",
                }:
                    return False
                reason = str(
                    (_item or {}).get("reason")
                    or (_item or {}).get("filter_reason")
                    or (_item or {}).get("_filter_reason")
                    or ""
                ).strip().lower()
                if not reason.startswith("token_mismatch:official"):
                    return False
                url = str((_item or {}).get("url") or "").strip()
                if not (
                    url
                    and self._is_novel_platform_url(url)
                    and self._is_novel_detail_url(url)
                ):
                    return False
                query_norm = self._normalize_kor_token(_query)
                if not query_norm:
                    return False
                title_blob = " ".join(
                    str((_item or {}).get(k) or "")
                    for k in ("title", "content", "snippet")
                )
                title_norm = self._normalize_kor_token(title_blob)
                if not title_norm:
                    return False
                for _registry in (KNOWN_TITLE_ABBREVIATIONS or {}, KNOWN_ABBREVIATIONS or {}):
                    for _alias, _full in (_registry or {}).items():
                        alias_norm = self._normalize_kor_token(str(_alias or ""))
                        full_norm = self._normalize_kor_token(str(_full or ""))
                        if (
                            len(alias_norm) >= 2
                            and alias_norm in query_norm
                            and len(full_norm) >= 4
                            and full_norm in title_norm
                        ):
                            return True
                return False

            recovered_filtered_official = 0
            for _filtered_item in _meta_filtered_preview:
                if not isinstance(_filtered_item, dict):
                    continue
                if not _filtered_official_detail_matches_known_alias(_filtered_item):
                    continue
                _url = str(_filtered_item.get("url") or "").strip()
                _url_norm = ConversationContext._normalize_url_for_dedup(_url)
                if not _url or _url in seen_urls or _url_norm in seen_urls_norm:
                    continue
                seen_urls.add(_url)
                seen_urls_norm.add(_url_norm)
                r_copy = _filtered_item.copy()
                r_copy["_query"] = _query
                r_copy["_purpose"] = _purpose
                r_copy["_bridge_filtered_recovered"] = True
                new_results.insert(0, r_copy)
                recovered_filtered_official += 1

            if recovered_filtered_official:
                print(
                    f"[{_ts()}] {self.emoji} ♻️ bridge filtered official detail 회수: "
                    f"{recovered_filtered_official}건 query='{_query[:80]}'",
                    file=sys.stderr,
                )

            new_results.extend(deferred_results)
            all_results.extend(new_results)

            duplicate_count = len(_result_list) - len(new_results) - filtered_count - self_ref_count
            hard_filter_info = f", 도메인차단 {filtered_count}개" if filtered_count > 0 else ""
            short_alias_filter_info = (
                f", short_alias_false_official {short_alias_false_official_count}개"
                if short_alias_false_official_count > 0
                else ""
            )
            soft_info = f", 비관련보존 {soft_filtered_count}개" if soft_filtered_count > 0 else ""
            dup_info = f", 중복 {duplicate_count}개 제거" if duplicate_count > 0 else ""
            self_ref_info = f", 자기참조 {self_ref_count}개 제거" if self_ref_count > 0 else ""
            bridge_filter_info = (
                f", bridge필터 {max(0, _meta_lang_filtered)}개{_bridge_reason_info}"
                if _meta_lang_filtered > 0
                else ""
            )
            retry_info = (
                f", retries {_meta_retries}, attempts {_meta_attempts}"
                if _meta_retries > 0 or _meta_attempts > 1
                else ""
            )
            degraded_info = ", degraded" if _meta_degraded else ""
            _accepted_count = len(_result_list)
            _new_count = len(new_results)
            _bridge_after_filter = _accepted_count
            _base_info = (
                f"new={_new_count}, accepted={_accepted_count}, bridge_raw={_meta_raw_total}, "
                f"bridge_after_filter={_bridge_after_filter}"
            )
            if _new_count <= 0 and _accepted_count > 0:
                _dup_removed = max(0, duplicate_count)
                _dup_sample_info = (
                    f" | 중복예시: {', '.join(duplicate_samples)}"
                    if duplicate_samples
                    else ""
                )
                _reason = (
                    f"bridge 응답 { _accepted_count }건 중 신규 0건 "
                    f"(기존 결과와 중복 {_dup_removed}건)"
                )
                print(
                    f"[{_ts()}] search results [bridge응답/신규없음]: {_reason} | {_base_info}"
                    f"{bridge_filter_info}{hard_filter_info}{short_alias_filter_info}, 중복 {_dup_removed}개"
                    f"{self_ref_info}{retry_info}{degraded_info}{_bridge_request_info}"
                    f"{_headless_info}{_direct_info}{_recovered_info}{_dup_sample_info}",
                    file=sys.stderr,
                )
            elif _new_count <= 0 and _accepted_count == 0:
                _state = "bridge필터후0" if _meta_raw_total > 0 else "upstream무결과"
                if _meta_raw_total > 0:
                    _reason = (
                        f"검색엔진 raw {_meta_raw_total}건이 있었지만 "
                        f"bridge 필터 후 0건"
                    )
                else:
                    _reason = "검색엔진 raw 결과 자체가 0건"
                print(
                    f"[{_ts()}] search results [{_state}]: {_reason} | {_base_info}"
                    f"{bridge_filter_info}{retry_info}{degraded_info}{_bridge_request_info}"
                    f"{_headless_info}{_direct_info}{_recovered_info}",
                    file=sys.stderr,
                )
            else:
                _reason = f"신규 결과 {_new_count}건 추가"
                print(
                    f"[{_ts()}] search results [신규추가]: {_reason} | {_base_info}"
                    f"{bridge_filter_info}{hard_filter_info}{short_alias_filter_info}{soft_info}{dup_info}{self_ref_info}"
                    f"{retry_info}{degraded_info}{_bridge_request_info}"
                    f"{_headless_info}{_direct_info}{_recovered_info}",
                    file=sys.stderr,
                )
            _raw_preview_toggle = os.getenv("PIPELINE_LOG_RAW_SEARCH_PREVIEW", "1").strip().lower()
            _raw_preview_enabled = _raw_preview_toggle in {"1", "true", "yes", "on"}
            try:
                _raw_preview_limit = int(os.getenv("PIPELINE_LOG_RAW_SEARCH_PREVIEW_LIMIT", "3"))
            except Exception:
                _raw_preview_limit = 3
            _raw_preview_limit = max(1, min(_raw_preview_limit, 10))
            _should_log_raw_preview = bool(
                _raw_preview_enabled
                and _meta_raw_preview
                and (
                    _meta_raw_total != _accepted_count
                    or _accepted_count == 0
                    or _meta_degraded
                )
            )
            if _should_log_raw_preview:
                print(
                    f"[{_ts()}] raw search preview [upstream before bridge filter]: "
                    f"showing {min(len(_meta_raw_preview), _raw_preview_limit)}/{_meta_raw_total}"
                    f"{_bridge_request_info}",
                    file=sys.stderr,
                )
                for _idx, _raw_item in enumerate(_meta_raw_preview[:_raw_preview_limit], 1):
                    if not isinstance(_raw_item, dict):
                        continue
                    _raw_title = str(_raw_item.get("title") or "제목없음").strip()[:80]
                    _raw_url = str(_raw_item.get("url") or "").strip()[:120]
                    _raw_content = str(_raw_item.get("content") or "").strip().replace("\n", " ")[:140]
                    _raw_engine = str(_raw_item.get("engine") or "").strip()
                    _raw_prefix = f"[{_raw_engine}] " if _raw_engine else ""
                    print(f"[{_ts()}]    [raw{_idx}] {_raw_prefix}{_raw_title}", file=sys.stderr)
                    if _raw_url:
                        print(f"[{_ts()}]        URL: {_raw_url}", file=sys.stderr)
                    if _raw_content:
                        print(f"[{_ts()}]        내용: {_raw_content}...", file=sys.stderr)
            _should_log_filtered_preview = bool(
                _raw_preview_enabled
                and _meta_filtered_preview
                and _meta_lang_filtered > 0
            )
            if _should_log_filtered_preview:
                print(
                    f"[{_ts()}] bridge filtered preview [language/noise filter]: "
                    f"showing {min(len(_meta_filtered_preview), _raw_preview_limit)}/{_meta_lang_filtered}"
                    f"{_bridge_request_info}",
                    file=sys.stderr,
                )
                for _idx, _filtered_item in enumerate(_meta_filtered_preview[:_raw_preview_limit], 1):
                    if not isinstance(_filtered_item, dict):
                        continue
                    _flt_title = str(_filtered_item.get("title") or "제목없음").strip()[:80]
                    _flt_url = str(_filtered_item.get("url") or "").strip()[:120]
                    _flt_content = str(_filtered_item.get("content") or "").strip().replace("\n", " ")[:140]
                    _flt_engine = str(_filtered_item.get("engine") or "").strip()
                    _flt_reason = str(_filtered_item.get("filter_reason") or "unknown").strip()
                    _flt_prefix = f"[{_flt_engine}] " if _flt_engine else ""
                    print(
                        f"[{_ts()}]    [filtered{_idx}] {_flt_prefix}{_flt_title} "
                        f"(reason={_flt_reason})",
                        file=sys.stderr,
                    )
                    if _flt_url:
                        print(f"[{_ts()}]        URL: {_flt_url}", file=sys.stderr)
                    if _flt_content:
                        print(f"[{_ts()}]        내용: {_flt_content}...", file=sys.stderr)
            if ctx_ref and hasattr(ctx_ref, "record_search_outcome"):
                try:
                    ctx_ref.record_search_outcome(
                        len(new_results),
                        raw_count=_meta_raw_total,
                        filtered_count=filtered_count,
                        duplicate_count=max(0, duplicate_count),
                        self_ref_count=self_ref_count,
                        degraded=_meta_degraded,
                        retries=_meta_retries,
                        attempts=_meta_attempts,
                        from_cache=bool(_search_meta.get("from_cache")),
                        purpose=str(_purpose or ""),
                        headless_used=_meta_headless_used,
                        headless_reason=_meta_headless_reason,
                        headless_count=_meta_headless_count,
                        headless_blocked=_meta_headless_blocked,
                        fallback_recovered=_meta_fallback_recovered,
                        degraded_recovered=_meta_degraded_recovered,
                        degraded_zero_suppressed=bool(_search_meta.get("suppressed_degraded_zero")),
                        direct_search_used=_meta_direct_used,
                        direct_search_reason=_meta_direct_reason,
                        direct_search_count=_meta_direct_count,
                        direct_search_providers=_meta_direct_providers,
                        direct_search_errors=_meta_direct_errors,
                    )
                except Exception:
                    pass

            if len(new_results) <= 0:
                if _accepted_count > 0:
                    _zero_streak = 0
                    _nonzero_total += 1
                else:
                    _zero_total += 1
                    if _meta_degraded:
                        _zero_streak = 0
                        print(
                            f"[{_ts()}] ⚠️ 무결과-인프라 구간 감지: zero_streak 누적 생략 "
                            f"(query='{_query}', purpose={_purpose})",
                            file=sys.stderr,
                        )
                    else:
                        _zero_streak += 1
            else:
                _zero_streak = 0
                _nonzero_total += 1

            if (
                _zero_stop_enabled
                and len(seen_queries) >= _zero_stop_min_queries
                and _zero_streak >= _zero_stop_streak_limit
                and _nonzero_total <= 1
            ):
                _remaining_has_critical = False
                for _, _, _, _r2 in sortable:
                    _q2 = str((_r2 or {}).get("query", "")).strip()
                    if not _q2:
                        continue
                    _q2_key = " ".join(_q2.split()).lower()
                    if _q2_key in seen_queries:
                        continue
                    _p2 = _purpose_key((_r2 or {}).get("purpose", ""))
                    if _p2 in _early_stop_critical_purposes:
                        _remaining_has_critical = True
                        break
                if _remaining_has_critical:
                    print(
                        f"[{_ts()}] ⚠️ 검색 조기 종료 보류: 연속 무결과 {_zero_streak}회 "
                        f"but critical-purpose queries remain",
                        file=sys.stderr,
                    )
                else:
                    print(
                        f"[{_ts()}] ⚡ 검색 조기 종료: 연속 무결과 {_zero_streak}회 "
                        f"(total={len(seen_queries)}, nonzero={_nonzero_total}, zero={_zero_total})",
                        file=sys.stderr,
                    )
                    return True

            for i, _r in enumerate(new_results[:7], 1):
                title = _r.get("title", "제목없음")[:60]
                url = _r.get("url", "")[:80]
                content = _r.get("content", "")[:100].replace("\n", " ")
                print(f"[{_ts()}]    [{i}] {title}", file=sys.stderr)
                if url:
                    print(f"[{_ts()}]        URL: {url}", file=sys.stderr)
                if content:
                    print(f"[{_ts()}]        내용: {content}...", file=sys.stderr)
            if _budget_profile.get("stop_after_official_hit") and new_results:
                _official_hit = any(
                    self._is_novel_platform_url(str((_r or {}).get("url") or ""))
                    and self._is_novel_detail_url(str((_r or {}).get("url") or ""))
                    for _r in new_results
                )
                if _official_hit:
                    if (
                        not _is_direct_worklike_alias_probe_query(_query, _purpose_key(_purpose))
                        and _has_unprocessed_direct_worklike_alias_probe()
                    ):
                        print(
                            f"[{_ts()}] ⚠️ 검색 조기 종료 보류: broad official_hit "
                            f"query='{_query[:80]}' but direct alias probes remain",
                            file=sys.stderr,
                        )
                        return False
                    if (
                        _purpose_key(_purpose) == "title_body_sanitized_platform_probe"
                        and _title_body_probe_context_hit_count(_query) < 2
                        and _has_unseen_specific_title_body_probe()
                    ):
                        print(
                            f"[{_ts()}] ⚠️ 검색 조기 종료 보류: broad title-body official_hit "
                            f"query='{_query[:80]}' but specific probes remain",
                            file=sys.stderr,
                        )
                        return False
                    if ctx_ref is not None:
                        ctx_ref.search_stop_reason = "official_hit"
                    print(
                        f"[{_ts()}] ⚡ 검색 조기 종료: profile={_profile_name}, official_hit",
                        file=sys.stderr,
                    )
                    return True
            if _profile_name == "core_fast_resolve" and _nonzero_total >= 2:
                if _has_unseen_specific_title_body_probe():
                    print(
                        f"[{_ts()}] ⚠️ 검색 조기 종료 보류: core_fast_resolve "
                        f"nonzero={_nonzero_total} but specific title-body probes remain",
                        file=sys.stderr,
                    )
                    return False
                if ctx_ref is not None:
                    ctx_ref.search_stop_reason = "core_fast_resolve_nonzero"
                print(
                    f"[{_ts()}] ⚡ 검색 조기 종료: profile=core_fast_resolve, nonzero={_nonzero_total}",
                    file=sys.stderr,
                )
                return True
            if _profile_name == "adjacent_meta_cheap" and _nonzero_total >= 1:
                if (
                    _purpose_key(_purpose) in {"title_body_sanitized_platform_probe", "title_anchor_official_probe"}
                    and _title_body_compact_anchor_active
                    and _has_unseen_specific_title_body_probe()
                    and not any(
                        self._is_novel_platform_url(str((_r or {}).get("url") or ""))
                        and self._is_novel_detail_url(str((_r or {}).get("url") or ""))
                        for _r in new_results
                    )
                ):
                    print(
                        f"[{_ts()}] ⚠️ 검색 조기 종료 보류: title-body non-official "
                        f"nonzero={_nonzero_total} but specific probes remain",
                        file=sys.stderr,
                    )
                    return False
                if ctx_ref is not None:
                    ctx_ref.search_stop_reason = "adjacent_meta_cheap_nonzero"
                print(
                    f"[{_ts()}] ⚡ 검색 조기 종료: profile=adjacent_meta_cheap, nonzero={_nonzero_total}",
                    file=sys.stderr,
                )
                return True
            if _profile_name == "quarantine_candidate" and (_nonzero_total >= 1 or _zero_total >= 1):
                if ctx_ref is not None:
                    ctx_ref.search_stop_reason = "quarantine_candidate_early_stop"
                print(
                    f"[{_ts()}] ⚡ 검색 조기 종료: profile=quarantine_candidate, "
                    f"nonzero={_nonzero_total}, zero={_zero_total}",
                    file=sys.stderr,
                )
                return True
            return False

        _search_executor: Optional[ThreadPoolExecutor] = None
        if _can_parallel_search:
            _search_executor = ThreadPoolExecutor(max_workers=_search_concurrency)

        try:
            _cursor = 0
            _stop_search = False
            while _cursor < len(sortable) and not _stop_search:
                if len(seen_queries) >= max_q:
                    break

                _batch: List[Tuple[str, Any, str]] = []
                while _cursor < len(sortable):
                    _, _, _, req = sortable[_cursor]
                    _cursor += 1
                    if len(seen_queries) >= max_q:
                        break

                    query = str(req.get("query", "")).strip()
                    if not query:
                        continue

                    q_key = " ".join(query.replace('"', "").replace("'", "").split()).lower()
                    if q_key in seen_queries:
                        continue

                    purpose = req.get("purpose", "search")
                    purpose_key = _purpose_key(purpose)
                    _family_tokens = self._extract_query_tokens(query, keep_generic=False)
                    _family_key = f"{purpose_key}|{' '.join(_family_tokens[:2])}"
                    _family_limit = 3 if purpose_key == "title_body_sanitized_platform_probe" else 2
                    if (
                        _family_key
                        and query_family_counts.get(_family_key, 0) >= _family_limit
                        and _nonzero_total <= 0
                        and _profile_name in {"core_fast_resolve", "adjacent_meta", "adjacent_meta_cheap", "uncertain_core"}
                    ):
                        print(
                            f"[{_ts()}] 🧹 동일 계열 재검색 중단: family={_family_key} query='{query[:80]}'",
                            file=sys.stderr,
                        )
                        continue

                    _low_info_reason = _get_low_info_query_reason(query, purpose_key)
                    if _low_info_reason:
                        print(
                            f"[{_ts()}] 🧹 저정보 쿼리 스킵: purpose={purpose_key} "
                            f"reason={_low_info_reason} query='{query[:80]}'",
                            file=sys.stderr,
                        )
                        continue

                    if _smart_prune_on:
                        _cap = _purpose_caps.get(purpose_key)
                        _effective_cap = _cap
                        if _cap is not None and purpose_key == "discourse_suggestion":
                            _q_norm_for_cap = self._normalize_kor_token(query)
                            _anchor_hit = 0
                            if _q_norm_for_cap and _anchor_terms_for_prune:
                                for _a in _anchor_terms_for_prune:
                                    if _a and _a in _q_norm_for_cap:
                                        _anchor_hit += 1
                                        if _anchor_hit >= 2:
                                            break
                            if ("작가" in query) and (_anchor_hit >= 2):
                                _effective_cap = _cap + 1
                        if _effective_cap is not None and _purpose_exec_counts.get(purpose_key, 0) >= _effective_cap:
                            print(
                                f"[{_ts()}] 🧹 목적별 상한으로 스킵: purpose={purpose_key} cap={_effective_cap} query='{query[:80]}'",
                                file=sys.stderr,
                            )
                            continue

                        if purpose_key in _low_signal_purposes and _anchor_terms_for_prune:
                            _q_norm = self._normalize_kor_token(query)
                            if not any(_a in _q_norm for _a in _anchor_terms_for_prune):
                                print(
                                    f"[{_ts()}] 🧹 저신호 쿼리 스킵(앵커 미포함): purpose={purpose_key} query='{query[:80]}'",
                                    file=sys.stderr,
                                )
                                continue
                            if purpose_key in {"abbreviation_meaning_search", "abbreviation_fullname_search", "ambiguous_meaning_track"}:
                                _head = self._normalize_kor_token(query.split()[0] if query.split() else query)
                                if len(_head) < 3:
                                    print(
                                        f"[{_ts()}] 🧹 저신호 의미쿼리 스킵(토큰 너무 짧음): purpose={purpose_key} query='{query[:80]}'",
                                        file=sys.stderr,
                                    )
                                    continue

                    try:
                        _max_query_len = int(os.getenv("LLM_MAX_SEARCH_QUERY_LEN", "180"))
                    except Exception:
                        _max_query_len = 180
                    _max_query_len = max(80, min(_max_query_len, 500))
                    _is_site_scoped = "site:" in query.lower()
                    _len_limit = _max_query_len
                    if _is_site_scoped and purpose in {"official_title_verify", "platform_title_search"}:
                        _len_limit = max(_len_limit, 260)
                    if len(query) > _len_limit:
                        print(
                            f"[{_ts()}] ⚠️ 검색 쿼리 너무 김 ({len(query)}자 > {_len_limit}) → 스킵: {query[:60]}...",
                            file=sys.stderr,
                        )
                        continue

                    seen_queries.add(q_key)
                    if _family_key:
                        query_family_counts[_family_key] = query_family_counts.get(_family_key, 0) + 1
                    print(f"[{_ts()}] 🔍 검 {query} (목적: {purpose})", file=sys.stderr)
                    if _smart_prune_on:
                        _purpose_exec_counts[purpose_key] = _purpose_exec_counts.get(purpose_key, 0) + 1
                    if ctx_ref and hasattr(ctx_ref, "mark_executed_query"):
                        ctx_ref.mark_executed_query(query)
                    _batch.append((query, purpose, q_key))

                    if not _can_parallel_search or len(_batch) >= _search_concurrency:
                        break

                if not _batch:
                    continue

                _batch_outcomes: List[Tuple[List[Dict[str, Any]], Dict[str, Any]]] = []
                if _search_executor is not None and len(_batch) > 1:
                    print(
                        f"[{_ts()}] ⚡ 검색 병렬 실행: {len(_batch)}건 (workers={min(_search_concurrency, len(_batch))})",
                        file=sys.stderr,
                    )
                    _ordered: List[Optional[Tuple[List[Dict[str, Any]], Dict[str, Any]]]] = [None] * len(_batch)
                    _future_map = {
                        _search_executor.submit(_invoke_search_call, _q, _p, _qk): _idx
                        for _idx, (_q, _p, _qk) in enumerate(_batch)
                    }
                    for _future in as_completed(_future_map):
                        _batch_idx = _future_map[_future]
                        try:
                            _ordered[_batch_idx] = _future.result()
                        except Exception as e:
                            _ordered[_batch_idx] = ([], {"degraded": True, "possible_throttle": True, "error": str(e)})
                    _batch_outcomes = [
                        _item if _item is not None else ([], {"degraded": True, "possible_throttle": True, "error": "missing_result"})
                        for _item in _ordered
                    ]
                else:
                    for _q, _p, _qk in _batch:
                        try:
                            _batch_outcomes.append(_invoke_search_call(_q, _p, _qk))
                        except Exception as e:
                            _batch_outcomes.append(([], {"degraded": True, "possible_throttle": True, "error": str(e)}))

                for (_query, _purpose, _q_key), (_result_list, _search_meta) in zip(_batch, _batch_outcomes):
                    try:
                        if _process_search_outcome(_query, _purpose, _result_list, _search_meta):
                            _stop_search = True
                            break
                    except Exception as e:
                        print(f"[{_ts()}] 🔍 검색 에러: {e}", file=sys.stderr)
        finally:
            if _search_executor is not None:
                _search_executor.shutdown(wait=True)
        
        # 우선순위 재정렬적용
        if all_results:
            all_results = self._prioritize_search_results(all_results)
            print(f"[{_ts()}] 🎯 검색 결과 우선순위 재정렬 완료 (총{len(all_results)}개", file=sys.stderr)
            try:
                _preview_default = "8" if self.parallel_count > 1 else "20"
                _preview_limit = int(os.getenv("LLM_REORDER_PRETTY_LIMIT", _preview_default))
            except Exception:
                _preview_limit = 8 if self.parallel_count > 1 else 20
            _preview_limit = max(0, min(_preview_limit, 50))
            if _preview_limit > 0:
                def _host_of(_url: str) -> str:
                    try:
                        from urllib.parse import urlparse
                        return (urlparse(str(_url or "")).hostname or "").lower()
                    except Exception:
                        return ""

                def _is_low_signal_platform_url(_url: str) -> bool:
                    _u = str(_url or "").lower()
                    if not _u:
                        return False
                    if any(k in _u for k in ("detailsearch", "action=search", "/search?", "menu=detailsearchv2")):
                        return True
                    if any(k in _u for k in ("freeboard", "forum", "community", "board", "arena")):
                        return True
                    if "square.munpia.com" in _u:
                        return True
                    return False

                def _tag_of(_host: str, _url: str) -> str:
                    if any(_host == d or _host.endswith("." + d) for d in self._OFFICIAL_PLATFORM_DOMAINS):
                        if _is_low_signal_platform_url(_url):
                            return "community"
                        return "official_platform"
                    if ("namu.wiki" in _host) or ("thewiki.kr" in _host) or ("wikipedia.org" in _host):
                        return "official_wiki"
                    if any(k in _host for k in ("dcinside", "fmkorea", "ruliweb", "arca.live")):
                        return "community"
                    return "other"

                def _clean_log_text(_s: Any) -> str:
                    _raw = str(_s or "")
                    _raw = _raw.replace("\r", " ").replace("\n", " ").replace("\t", " ")
                    return re.sub(r"\s+", " ", _raw).strip()

                _top_n = min(len(all_results), _preview_limit)
                print(
                    f"[{_ts()}] 🎯 📚 재정렬 결과(pretty) Top{_top_n}",
                    file=sys.stderr,
                )
                for _idx, _r in enumerate(all_results[:_top_n], 1):
                    _eid = str(_r.get("_evidence_id") or f"T{_idx:03d}")
                    _purpose = str(_r.get("_purpose") or "-")
                    _query = _clean_log_text(_r.get("_query") or "")
                    _title = _clean_log_text(_r.get("title") or "제목없음")
                    _url = _clean_log_text(_r.get("url") or "")
                    _host = _host_of(_url)
                    _tag = _tag_of(_host, str(_r.get("url") or ""))
                    print(
                        f"[{_ts()}]    [R{_idx:02d}][{_eid}][{_tag}] purpose={_purpose}",
                        file=sys.stderr,
                    )
                    print(
                        f"[{_ts()}]       제목: {_title[:120]}",
                        file=sys.stderr,
                    )
                    if _url:
                        print(
                            f"[{_ts()}]       URL : {_url[:160]}",
                            file=sys.stderr,
                        )
                    if _query:
                        print(
                            f"[{_ts()}]       from_query: {_query[:120]}",
                            file=sys.stderr,
                        )
                _catalog_default = "0" if self.parallel_count > 1 else "1"
                _print_catalog = os.getenv("LLM_REORDER_PRINT_CATALOG", _catalog_default).strip().lower() in {"1", "true", "yes", "on"}
                if _print_catalog:
                    _catalog_max = max(_top_n, min(len(all_results), 40))
                    print(
                        f"[{_ts()}] 🎯 📚 검색 근거 카탈로그 (임시 Pre-EID, Top{_catalog_max})",
                        file=sys.stderr,
                    )
                    for _idx, _r in enumerate(all_results[:_catalog_max], 1):
                        _eid = str(_r.get("_evidence_id") or f"T{_idx:03d}")
                        _title = _clean_log_text(_r.get("title") or "제목없음")
                        _url = _clean_log_text(_r.get("url") or "")
                        if _url:
                            print(f"[{_eid}] {_title[:90]} | {_url[:180]}", file=sys.stderr)
                        else:
                            print(f"[{_eid}] {_title[:90]}", file=sys.stderr)
        
        return all_results
